(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.018+t*0.3)*20+Math.cos(y*0.013-t*0.22)*15;
  const wy1 = Math.cos(y*0.016-t*0.28)*20+Math.sin(x*0.015+t*0.32)*15;
  const wx2 = Math.sin((x+wx1)*0.025+t*0.5)*10+Math.cos((y+wy1)*0.02-t*0.4)*8;
  const wy2 = Math.cos((y+wy1)*0.022-t*0.45)*10+Math.sin((x+wx1)*0.019+t*0.55)*8;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,220+Math.sin(t*0.75+4)*40,0.05,2.8]
  ];
  let aS=0,iS=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
  }
  const n=src.length,act=aS/n,inh=iS/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.07+sy*0.05-t*1.5)*0.15+Math.cos(sx*0.05-sy*0.08+t*1.8)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08+ang*2-t*0.8)*0.2;
  const sp3=Math.cos(dist*0.03-ang*5+t*1.0)*0.15;
  const spiral=sp1+sp2+sp3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const n1=Math.sin(sx*0.1+t*0.7)*Math.cos(sy*0.12-t*0.5);
  const n2=Math.sin(sx*0.2-t*0.9)*Math.cos(sy*0.18+t*0.6)*0.5;
  const n3=Math.sin(sx*0.35+t*1.1)*Math.cos(sy*0.3-t*0.8)*0.25;
  const fractal=n1+n2+n3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+fractal*0.2)*2.0);
  const reaction2=Math.tanh((act*0.5+inh*0.3+bg*0.4-spiral*0.3)*1.8);
  const blend=reaction*0.6+cell*0.15+reaction2*0.25,v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[10,40,80],[15,75,105],[20,120,130],
    [45,155,120],[140,175,80],[200,180,60],[215,140,55],
    [210,100,60],[185,65,65],[140,40,70],[90,25,60],
    [50,18,55],[20,15,48],[5,12,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.7?1.12:1.0;
  const glow=Math.max(0,reaction2*0.15);
  const tl=lum*edge+glow;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*tl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*tl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*tl)|0
  ];
}
